def transform(grid):
    from collections import Counter
    n, m = len(grid), max(map(len, grid))
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(n):
        for c in range(len(grid[r])):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < n and 0 <= xx < len(grid[yy]) and grid[yy][xx] != bg and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            objects.append(cells)

    panels = []
    for cells in objects:
        fill = Counter(grid[r][c] for r, c in cells).most_common(1)[0][0]
        accents = [(r, c, grid[r][c]) for r, c in cells if grid[r][c] != fill]
        ys = [r for r, c in cells]
        xs = [c for r, c in cells]
        candidates = []
        for r0 in range(max(0, min(ys) - 5), min(n - 5, max(ys) + 1)):
            for c0 in range(max(0, min(xs) - 5), min(m - 5, max(xs) + 1)):
                if accents and not all(r0 <= r < r0 + 6 and c0 <= c < c0 + 6 for r, c, v in accents):
                    continue
                count = sum(r0 <= r < r0 + 6 and c0 <= c < c0 + 6 for r, c in cells)
                candidates.append((count, r0, c0))
        if candidates:
            _, r0, c0 = max(candidates, key=lambda z: (z[0], z[2], z[1]))
        else:
            r0, c0 = min(ys), min(xs)
        size = max(max(ys) - min(ys), max(xs) - min(xs)) + 1
        panels.append((fill, accents, r0, c0, size))

    canvas = next((p for p in panels if any(v == 5 for r, c, v in p[1])), panels[0])
    fill = canvas[0]
    size = canvas[4]
    out = [[fill] * size for _ in range(size)]
    for _, accents, r0, c0, _ in panels:
        for r, c, v in accents:
            rr, cc = r - r0, c - c0
            if 0 <= rr < size and 0 <= cc < size:
                out[rr][cc] = v
    return out
